class Entry {
    int length;
    String sequenceBetween;
    int balance0;
    int balance1;

    Entry(int length, String sequenceBetween, int balance0, int balance1) {
        this.length = length;
        this.sequenceBetween = sequenceBetween;
        this.balance0 = balance0;
        this.balance1 = balance1;
    }
}

